/** A checklist item. auto_check = the system check that pre-answers it (null: the reviewer decides). */
export interface CriterionOut {
  criterion_id: number;
  code: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  applies_to: "Admission" | "OpdVisit" | "Both";
  /** Who fixes a No: the record's Doctor, or the ward's Nursing team */
  responsible: "Doctor" | "Nursing";
  title: string;
  guidance: string | null;
  auto_check: "admission_reason" | "provisional_diagnosis" | "care_plan" | "discharge_summary" | "transfer_record" | "vitals_on_schedule" | "doses_charted" | "general_consent" | "procedure_consent" | "operative_note" | "anaesthesia_record" | "safety_checklist" | "death_certificate" | "autopsy_report" | "chief_complaint" | "visit_diagnosis" | "visit_plan" | "notes_signed" | "notes_timely" | "icd_coded" | "verbal_orders" | "wristband" | "own_medicines" | "critical_results" | "diagnostic_turnaround" | "nutrition_screening" | "nursing_care_plan" | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

export interface AutoResultOut {
  result: "Pass" | "Fail" | "NA";
  detail: string;
  responsible_employee_id: number | null;
}

export interface AnswerOut {
  answer: "Yes" | "No" | "NA";
  comment: string | null;
}

export interface ItemDeficiencyOut {
  deficiency_id: number;
  criterion_code: string;
  category: "Timeliness" | "Legibility" | "Completeness";
  description: string;
  status: "Open" | "Corrected" | "Acknowledged" | "Withdrawn";
}

export interface RecordReviewIn {
  /** By criterion code: every applicable active checklist item */
  answers: Record<string, AnswerIn>;
  note?: string | null;
}

export interface AnswerIn {
  answer: "Yes" | "No" | "NA";
  /** Required for No, and for an answer that differs from the system check */
  comment?: string | null;
}

/** My records to review — GET /api/v1/quality/record-review-items/mine (who may call: holders of quality.review.perform). */
export function myItems(query?: { include_reviewed?: boolean }): Promise<ItemListOut[]> {
  return api<ItemListOut[]>("GET", withQuery(`/quality/record-review-items/mine`, query), undefined);
}

/** A sampled record with its checklist and the system's answers — GET /api/v1/quality/record-review-items/{item_id} (who may call: holders of quality.review.perform or quality.review.manage). */
export function getItem(item_id: number): Promise<ItemOut> {
  return api<ItemOut>("GET", `/quality/record-review-items/${item_id}`, undefined);
}

/** Submit the review (final) — POST /api/v1/quality/record-review-items/{item_id}/review (who may call: holders of quality.review.perform). */
export function reviewQualityRecordItems(item_id: number, body: RecordReviewIn): Promise<ItemOut> {
  return api<ItemOut>("POST", `/quality/record-review-items/${item_id}/review`, body);
}

/** The review checklist — GET /api/v1/quality/record-review/criteria (who may call: holders of quality.review.manage or quality.review.view or quality.review.perform). */
export function criteria(query?: { active_only?: boolean }): Promise<CriterionOut[]> {
  return api<CriterionOut[]>("GET", withQuery(`/quality/record-review/criteria`, query), undefined);
}
